 while(this.upgrades.length){const u=this.upgrades[0];if(u.source==='level'&&!teamHasGrowth(this)){this.upgrades.shift();this.convertGrowthTicket();continue;}if(u.source==='ticket'&&!eligible(this,u.id).length){u.id=this.ticketGrowthOwner();delete u.choices;if(!u.id){this.upgrades.shift();continue;}}u.choices??=u.gold?rollGold(this):rollGrowth(this,u.id);if(!u.choices.length){this.upgrades.shift();this.convertGrowthTicket();if(u.advance)this.advanceFloor();continue;}this.setModal('upgrade');this.event('upgrade',{upgrade:u});return;}
